@push('scripts')
<script>
(() => {
    const monthly = document.getElementById('monthly_tuition');
    const months = document.getElementById('billable_months');
    const semester = document.getElementById('semester_months');
    const currency = document.getElementById('currency');
    const show = count => {
        const parts = monthly.value.split('.');
        const cents = Number(parts[0] || 0) * 100 + Number((parts[1] || '').padEnd(2, '0').slice(0, 2));
        const total = cents * Number(count || 0);
        return `${Math.trunc(total / 100)}.${String(total % 100).padStart(2, '0')} ${currency.value}`;
    };
    const update = () => {
        document.getElementById('annual-preview').value = show(months.value);
        document.getElementById('semester-preview').value = show(semester.value);
    };
    [monthly, months, semester, currency].forEach(field => field.addEventListener('input', update));
    update();
})();
</script>
